/* aucun moment aléatoire avant ce jour : espèces capturées ou transférées en cours de vie */
const MIN_D={perroquet:400,python:60,iguane:90,tortueterre:3000,poissonclown:400,fennec:100,loutre:300,macaque:1100,beagle:240,saumon:400,chinchilla:240,lion:5,elephanttour:3650};
function tagOK(I,k,S){const t=TAGS[k]||[];
  if(I.req&&!I.req.every(x=>t.includes(x)))return false;
  if(I.any&&!I.any.some(x=>t.includes(x)))return false;
  if(I.exc&&I.exc.some(x=>t.includes(x)))return false;
  if(I.lieuNot&&S&&I.lieuNot.some(w=>S.lieu.includes(w)))return false;
  return true}

